def transform(g):
    from collections import Counter
    H,W=len(g),len(g[0]); out=[]
    for bi in range(H//3):
        row=[]
        for bj in range(W//3):
            blk=[g[r][c] for r in range(bi*3,bi*3+3) for c in range(bj*3,bj*3+3)]
            cnt=Counter(v for v in blk if v not in (0,5))
            row.append(cnt.most_common()[0][0] if (0 not in blk and cnt) else 0)
        out.append(row)
    return out
